				<div class="elementor-element elementor-element-d52e213 elementor-widget elementor-widget-text-editor" data-id="d52e213" data-element_type="widget" data-e-type="widget" data-widget_type="text-editor.default">
									<p style="text-align:center;font-family:Space Grotesk,sans-serif;font-weight:700;font-size:12.5px;letter-spacing:2px;text-transform:uppercase;color:#7C3AED;margin:0"><span style="display:inline-block;width:22px;height:3px;background:linear-gradient(100deg,#FF2E7E,#7C3AED);border-radius:2px;margin-right:8px;vertical-align:middle"></span>FAQs</p>								</div>
				<div class="elementor-element elementor-element-78f16954 elementor-widget elementor-widget-heading" data-id="78f16954" data-element_type="widget" data-e-type="widget" data-widget_type="heading.default">
					<h2 class="elementor-heading-title elementor-size-default">Plastic surgery clinic marketing — <span class="hl">before you ask</span></h2>				</div>
